    row=(w*((bpp+7)//8 if bpp else 1)+3)&~3
    if imgsize==0 and w>0 and h>0 and w<100000: imgsize=row*h
    hdr=b'BM'+struct.pack('<IHHI',pixoff+imgsize,0,0,pixoff)
    info=struct.pack('<IiiHHIIiiII',hdrsize,w,h,planes,bpp,comp,imgsize,2835,2835,0,0)
    return hdr+info+extra

for w,h in [(0,0),(0,1),(1,0),(-1,1),(1,-1),(-2147483648,1),(2147483647,1),(1,2147483647),
            (65535,65535),(46341,46341),(1000000,1)]:
    check(bmp_custom(w,h), f"bmp-{w}x{h}")
for bpp in [0,1,2,4,8,16,24,32,33,255,65535]:
    check(bmp_custom(2,2,bpp=bpp,extra=b"\x00"*1024), f"bmp-bpp{bpp}")
for comp in [0,1,2,3,4,5,6,99,0xffffffff]:
    check(bmp_custom(2,2,comp=comp,extra=b"\x00"*256), f"bmp-comp{comp}")
for off in [0,1,14,53,54,55,100,0x7fffffff,0xffffffff]:
    check(bmp_custom(2,2,pixoff=off,extra=b"\x00"*256), f"bmp-off{off}")

