# 4. MIF extremes
for w,h in [(0,0),(1,1),(2147483647,1),(65535,65535),(100000,100000)]:
    check(mif(w,h)[:200], f"mif-{w}x{h}")
for d in [0,1,8,16,31,32,255,65535]:
