import struct, subprocess

BIN = "/workspace/artifacts/target/jasper"

def run(data, outfmt="pnm", timeout=8):
    with open("fz.in","wb") as f: f.write(data)
    try:
        p = subprocess.run([BIN,"--input","fz.in","--output","fz.out","--output-format",outfmt],
                           capture_output=True, timeout=timeout)
        return p.returncode, p.stderr[:300]
    except subprocess.TimeoutExpired:
        return "timeout", b""

SOC = b"\xff\x4f"
EOC = b"\xff\xd9"

def seg(marker, payload):
    return struct.pack(">H", marker) + struct.pack(">H", 2+len(payload)) + payload

def siz(Lsiz=38, Rsiz=0, Xsiz=1, Ysiz=1, XOsiz=0, YOsiz=0, XTsiz=1, YTsiz=1, XTOsiz=0, YTOsiz=0, comps=[(0,1,1)]):
    Csiz=len(comps)
    p = struct.pack(">HHIIIIIIIIH", Lsiz, Rsiz, Xsiz, Ysiz, XOsiz, YOsiz, XTsiz, YTsiz, XTOsiz, YTOsiz, Csiz)
    for (ssiz,xr,yr) in comps:
        p += struct.pack(">BBB", ssiz, xr, yr)
    return seg(0xff51, p)

def cod(scod=0, prog=0, layers=1, mct=0, ndl=5, cbw=4, cbh=4, cbstyle=0, xform=1, precincts=b""):
    p = struct.pack(">BBHBBBxBBB", scod, prog, layers, mct, ndl, cbw, cbh, cbstyle, xform) + precincts
    # note: layout is B(scod) I? actually: Scod(1), ProgressionOrder(1), NumLayers(2), MCT(1), NDL(1), cbw(1), cbh(1), cbstyle(1), xform(1)
    p = struct.pack(">BBHBBBBBBB", scod, prog, layers, mct, ndl, cbw, cbh, cbstyle, xform) + precincts
    return seg(0xff52, p)

def qcd(sqcd=0, guards=2, steps=b""):
    return seg(0xff5c, struct.pack(">B", (guards<<5)|sqcd) + steps)

def check(data, tag, outfmt="pnm"):
    rc, err = run(data, outfmt)
    msg = err.decode(errors="replace").replace("\n"," | ")[:130]
    if rc not in (0,1) and rc != "timeout":
        print("CRASH", tag, "rc=", rc, msg, flush=True)
    elif rc == "timeout":
        print("TIMEOUT", tag, flush=True)
    else:
        print("ok", tag, "rc=", rc, msg, flush=True)

# baseline
base = SOC + siz() + cod() + qcd(steps=b"\x4a") + b"\xff\x93" + b"\x00" + EOC
check(base, "jpc-base")

# SIZ extremes
for X,Y in [(0,0),(0,1),(1,0),(0xffffffff,1),(1,0xffffffff),(0xffffffff,0xffffffff),
            (2147483647,2147483647),(65536,65536)]:
    check(SOC + siz(Xsiz=X, Ysiz=Y) + cod() + qcd(steps=b"\x4a") + b"\xff\x93\x00" + EOC, f"jpc-siz-{X}x{Y}")
for XO,YO in [(1,1),(2,2),(0xffffffff,0xffffffff),(2147483647,0),(0,2147483647)]:
    check(SOC + siz(XOsiz=XO, YOsiz=YO) + cod() + qcd(steps=b"\x4a") + b"\xff\x93\x00" + EOC, f"jpc-off-{XO}x{YO}")
# Xsiz < XOsiz (wrap)
check(SOC + siz(Xsiz=1, XOsiz=0xffffffff) + cod() + qcd(steps=b"\x4a") + b"\xff\x93\x00" + EOC, "jpc-wrapX")
check(SOC + siz(Xsiz=1, Ysiz=1, XOsiz=0xffffffff, YOsiz=0xffffffff) + cod() + qcd(steps=b"\x4a") + b"\xff\x93\x00" + EOC, "jpc-wrapXY")
# many components
for n in [0,1,255,256,16384,65535]:
    comps=[(7,1,1)]*min(n,65535)
    check(SOC + siz(comps=comps) + cod() + qcd(steps=b"\x4a") + b"\xff\x93\x00" + EOC, f"jpc-nc{n}")
# weird component subsampling
for xr,yr in [(0,0),(0,1),(1,0),(255,255)]:
    check(SOC + siz(Xsiz=16,Ysiz=16,comps=[(7,xr,yr)]) + cod() + qcd(steps=b"\x4a") + b"\xff\x93\x00" + EOC, f"jpc-sub{xr}x{yr}")
# ssiz extremes
for ss in [0,1,7,8,31,32,37,38,127,128,255]:
    check(SOC + siz(comps=[(ss,1,1)]) + cod() + qcd(steps=b"\x4a") + b"\xff\x93\x00" + EOC, f"jpc-ssiz{ss}")
# COD extremes
for ndl in [0,1,32,33,255]:
    check(SOC + siz() + cod(ndl=ndl) + qcd(steps=b"\x4a") + b"\xff\x93\x00" + EOC, f"jpc-ndl{ndl}")
for layers in [0,1,65535]:
    check(SOC + siz() + cod(layers=layers) + qcd(steps=b"\x4a") + b"\xff\x93\x00" + EOC, f"jpc-layers{layers}")
for cbw,cbh in [(0,0),(10,10),(11,11),(255,255),(8,9)]:
    check(SOC + siz() + cod(cbw=cbw,cbh=cbh) + qcd(steps=b"\x4a") + b"\xff\x93\x00" + EOC, f"jpc-cb{cbw}x{cbh}")
# truncated marker segments
check(SOC + struct.pack(">H",0xff51) + struct.pack(">H",40) + b"\x00"*4, "jpc-truncSIZ")
check(SOC + siz() + b"\xff\x52\xff", "jpc-truncCOD")
# SIZ Lsiz mismatch
check(SOC + siz(Lsiz=5) + cod() + qcd(steps=b"\x4a") + b"\xff\x93\x00" + EOC, "jpc-Lsiz5")
check(SOC + siz(Lsiz=65535) + cod() + qcd(steps=b"\x4a") + b"\xff\x93\x00" + EOC, "jpc-LsizBig")
print("done")
